// Shared Unified Data Access Helper for Single Source of Truth
function getUnifiedDailyFGProductionData() {
    let deletedIds = new Set();
    try {
        if (typeof localStorage !== 'undefined') {
            const delSaved = localStorage.getItem('deleted_fg_production_entry_ids');
            if (delSaved) {
                const parsedDel = JSON.parse(delSaved);
                if (Array.isArray(parsedDel)) {
                    deletedIds = new Set(parsedDel.map(String));
                }
            }
        }
    } catch(e) {}

    let entries = [];
    if (typeof RAW_PRODUCTION_DATA !== 'undefined' && Array.isArray(RAW_PRODUCTION_DATA)) {
        entries = RAW_PRODUCTION_DATA.map((r, idx) => {
            const item = { ...r };
            if (!item._entryIndex) item._entryIndex = 'raw_' + idx;
            return item;
        }).filter(r => !deletedIds.has(String(r._entryIndex)));
    }
    try {
        if (typeof localStorage !== 'undefined') {
            const custom = localStorage.getItem('custom_fg_production_entries');
            if (custom) {
                const parsed = JSON.parse(custom);
                if (Array.isArray(parsed)) {
                    const validCustom = parsed.filter(r => !deletedIds.has(String(r._entryIndex)));
                    // Prepend custom entries so newest/edited entries have priority
                    entries = [...validCustom, ...entries];
                }
            }
        }
    } catch(e) {
        console.error("Error reading custom_fg_production_entries:", e);
    }
    return entries;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { RAW_PRODUCTION_DATA, getUnifiedDailyFGProductionData };
}


